(function(){try{var D=window.DATA;if(D&&D.physio){D.physio=D.physio.filter(function(x){return [6,34,66].indexOf(x.n)<0});D.physio.forEach(function(x){if(x.n===53){x.q='The ABO blood group of an individual with anti-B antibodies in plasma and A antigen on RBCs is:';x.o=['A','B','AB','O']}})}}catch(e){}})();
var PHQ=[{"s": "ESR", "p": "3", "q": "What are the factors affecting ESR?", "a": ["1) Plasma proteins: ESR increases when fibrinogen and globulins increase. They are positively charged, so they reduce the negative charge of the RBCs, which lowers RBC repulsion and helps rouleaux formation.", "ESR also increases when albumin decreases.", "2) RBC count."], "src": "f", "lo": 0}, {"s": "ESR", "p": "2-3", "q": "Name the physiological and pathological variations in ESR.", "a": ["Increased, physiological: in females during menstruation and pregnancy; in increased temperature; after muscular exercise.", "Increased, pathological: inflammation and tissue destruction (acute and chronic infections e.g. tonsillitis, appendicitis, tuberculosis; severe trauma e.g. fractures; myocardial infarction; degenerative and neoplastic disease; rheumatic arthritis); all anemias except spherocytosis, sickle cell anemia and pernicious anemia; all malignant diseases; nephrosis (albumin drops, fibrinogen and globulins rise); trauma, surgery and any large-scale tissue injury.", "Decreased: polycythemia; anemias of spherocytosis, pernicious anemia and sickle cell anemia; afibrinogenemia."], "src": "f", "lo": 0}, {"s": "ESR", "p": "3", "q": "What is the clinical significance of ESR?", "a": ["ESR changes in a great variety of conditions, so it is not specific (not diagnostic) for any particular disease and gives no indication of the nature of the underlying disorder.", "Repeated ESR estimations help in: 1) prognosis, 2) follow up of the activity of the disease, 3) its response to treatment."], "src": "f", "lo": 0}, {"s": "ESR", "p": "1", "q": "Compare the two ESR methods (Wintrobe and Westergren).", "a": ["Wintrobe: oxalate is used as anticoagulant (citrate would dilute the sample too much).", "Westergren: citrate is used as anticoagulant. It is more sensitive than Wintrobe because its tube is long enough and has a larger diameter.", "Disadvantage of Westergren: citrate dilutes the red cells, which increases ESR, but fibrinogen and globulin are also diluted, which decreases ESR. Both neutralize each other."], "src": "f", "lo": 0}, {"s": "ESR", "p": "1-2", "q": "How is ESR measured by the Westergren method?", "a": ["Principle: with anticoagulant, the heavier red cells settle gradually in a narrow vertical tube. The rate in mm at the end of one hour is the ESR.", "Procedure: add 2 ml of venous blood to 0.5 ml Na-citrate (3.8%); mix but do not shake; suck the mixture into the Westergren tube up to mark 0; place it upright in the stand (22-27 C); after one hour read in millimeters the column of clear plasma above the sedimented RBCs.", "Tube: 300 mm long, diameter 2.5 mm, graduated 0-200."], "src": "f", "lo": 0}, {"s": "ESR", "p": "2", "q": "What are the ESR values in the results table?", "a": ["Male: first hour 5, second hour 8. Female: first hour 10, second hour 16.", "Note: the file writes the unit as \"ml\" in the table, but its principle says the ESR is in mm."], "src": "f", "lo": 1}, {"s": "ESR", "p": "1", "q": "ESR objectives: what should you be able to do after this experiment?", "a": ["1. Describe the clinical importance of doing ESR.", "2. Explain why red cells settle down when blood is kept in a tube.", "3. Indicate factors that affect their rate of settling.", "4. Name methods employed for its determination.", "5. Describe sources of error and precautions to be taken.", "6. Name the various conditions in which ESR is increased or decreased and the physiological basis."], "src": "f", "lo": 0}, {"s": "ESR", "p": "1", "q": "What are the relevance and principle of ESR? Why do red cells settle down in a tube?", "a": ["Relevance: ESR is often required to rule out the presence of organic disease and to follow the progress of a disease.", "Principle: blood is a suspension of cells in a fluid part (plasma). If an anticoagulant is added and the blood is allowed to stand in a narrow vertical tube, the red cells, being heavier than plasma, settle or sediment gradually.", "The rate, in mm, at which the red cells sediment is called ESR, and is recorded at the end of one hour."], "src": "f", "lo": 0}, {"s": "ESR", "p": "1-2", "q": "What are the apparatus and materials of the Westergren method?", "a": ["1. 5 ml disposable syringe with needle.", "2. Sterile cotton/gauze swabs moist with alcohol.", "3. Container.", "4. Sterile solution of 3.8% sodium citrate.", "5. Westergren tube and stand: a 300 mm long tube, diameter 2.5 mm, graduated from 0-200 from above downwards in its lower 2/3."], "src": "f", "lo": 0}, {"s": "ESR", "p": "1-2", "q": "Sources of error and precautions in ESR: what does the file say?", "a": ["The file does not give a separate list headed sources of error and precautions. What it states: with the Westergren method, citrate dilutes the red cells, which increases the ESR, but fibrinogen and globulin are also diluted, which decreases the ESR, and the two effects neutralize each other.", "In the Wintrobe method oxalate is the anticoagulant (using citrate would dilute the sample too much).", "Procedure points (p.2): mix the blood with the citrate but do not shake, keep the tube in the stand at room temperature 22-27 C, and read after one hour."], "src": "f", "lo": 0}, {"s": "ESR", "p": "3", "q": "What causes decrease the ESR?", "a": ["a. Polycythemia.", "b. Anemias: spherocytosis, pernicious anemia, sickle cell anemia.", "c. Afibrinogenemia."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "6", "q": "What are the normal levels and ranges of Hb at different ages?", "a": ["Male: 16 +/- 2 g/100 ml blood.", "Female: 14 +/- 2 g/100 ml blood.", "Newborn: 18 to 22 gm%."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "6", "q": "Compared to females, why are the hemoglobin levels higher in males?", "a": ["Male 16 +/- 2, female 14 +/- 2 g/100 ml.", "Testosterone in males stimulates erythropoietin and red cell production, so Hb is higher. In females, menstrual blood loss and the lack of this androgen effect keep it lower."], "src": "t", "lo": 0}, {"s": "Hemoglobin", "p": "6", "q": "Why is the hemoglobin level high in the newborns?", "a": ["Newborn Hb: 18 to 22 gm%.", "In the womb the fetus has relative hypoxia, which raises erythropoietin and red cell production, and fetal hemoglobin (HbF) carries oxygen with higher affinity. So the newborn has a high Hb at birth."], "src": "t", "lo": 0}, {"s": "Hemoglobin", "p": "6", "q": "What are the common causes of increased and decreased Hb readings?", "a": ["Increased: polycythemia.", "Decreased: anemia."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "4", "q": "What is the principle of Hb estimation (Sahli acid hematin method)?", "a": ["The Hb in a measured amount of blood is converted by dilute HCl into acid hematin, which is golden brown when diluted.", "The color intensity depends on Hb concentration.", "After dilution with water, the color is matched against golden brown glass rods."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "5", "q": "Describe the procedure of the Sahli method.", "a": ["1) Fill the graduated tube with 0.1 N HCl to the 20% mark (2 gm) or a little more, until the pipette tip is submerged.", "2) Sterilize the thumb tip with alcohol and let it dry.", "3) Prick with a sterile lancet, wipe away the first 2 drops, take 20 microliters of blood with the micropipette. Do not squeeze the finger.", "4) Wipe the blood on the pipette tip.", "5) Transfer the blood into the acid by immersing the tip at the bottom; expel gently and rinse the pipette 3-4 times.", "6) Mix with the stirrer until uniformly dark brown (acid hematin) and place beside the standard brown tubes. Dark brown at the bottom means poor mixing.", "7) Wait about 5 minutes.", "8) Add distilled water drop by drop until the color matches the standard tubes.", "9) Take the average of 3 readings: slightly darker than standard, exactly matching, slightly lighter."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "5-6", "q": "What is the difference between absolute and relative Hb scales?", "a": ["Absolute scale: the Hb tube is graduated directly in gm% (0-24).", "Relative scale: the tube is calibrated in percentage of normal (100% = 17 gm%), graded 0-160%. It is an old method."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "4", "q": "Hb estimation objectives: what should you be able to do?", "a": ["1. Indicate the relevance of this estimation.", "2. Which characteristics of Hb can be used to estimate its concentration.", "3. Explain the absolute and relative Hb scales.", "4. Determine Hb level by the Sahli acid haematin method.", "5. List the sources and degree of errors in this method.", "6. Name the advantages and disadvantages of this method.", "7. Name the other methods for Hb estimation.", "8. Indicate the normal level of Hb in different age groups and sexes.", "9. Describe the structure, synthesis and functions of Hb.", "10. Name the varieties and derivatives of Hb.", "11. Name common causes of increased and decreased levels of hemoglobin.", "12. Classify anaemia."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "4", "q": "What is the relevance of Hb estimation?", "a": ["It is a routine test in the outpatient department and a bedside test in indoor patients. It is indicated in all blood diseases, chronic infections, malignancy and renal failure."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "4", "q": "Which characteristics of Hb are used to estimate it, and what are the other methods?", "a": ["Sahli method: the Hb in a measured amount of blood is converted by dilute HCl into acid hematin, golden brown in color after dilution. The color intensity depends on the Hb concentration and is matched against golden brown glass rods.", "Other principles depending on characteristics of Hb: spectrophotometric method (the ability of Hb to reflect specific wavelengths of light); tests that depend on the known amount of iron in each gram of hemoglobin; gasometric method (the ability of Hb to combine with O2)."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "5", "q": "What apparatus and materials are used in the Sahli method?", "a": ["1. Sahli apparatus: a) two colored standard tubes (comparators); b) Hb tube, a graduated tube with a double scale, one scale in grams of Hb per deciliter (0-24) and the other in percentage of normal Hb (0-160%); c) a micropipette (20 microliters).", "2. Stirrer: thin glass rod for mixing.", "3. Pasteur pipette.", "4. Distilled water.", "5. 0.1 N HCl solution.", "6. Sterile lancets.", "7. Cotton/gauze swabs.", "8. 70% alcohol."], "src": "f", "lo": 0}, {"s": "Hemoglobin", "p": "5-6", "q": "Advantages, disadvantages and sources of error of the Sahli method: what does the file say?", "a": ["The file lists these as objectives (5 and 6) but does not give a list of them.", "Points it states in the procedure: dark brown color at the bottom of the tube indicates poor mixing; 0.1 N HCl can be used for dilution because it is transparent, but not tap water, because its salt content can cause turbidity; wait about 5 minutes before adding distilled water; do not squeeze the finger; wipe away the first 2 drops of blood.", "The file does not cover: structure, synthesis and functions of Hb, varieties and derivatives of Hb, and classification of anemia (objectives 9, 10 and 12 are listed only)."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "7", "q": "What is MCV and how is it calculated?", "a": ["Mean corpuscular volume: the average volume of a single RBC.", "MCV = (H.V / No. of RBCs in millions) x 10 = 90 cubic micron (normal 74-95)."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "7", "q": "What is MCH and how is it calculated?", "a": ["Mean corpuscular hemoglobin: the average amount of Hb in one RBC.", "MCH = (Hb / No. of RBCs in millions) x 10 = 30 picograms (normal 27-32 pg).", "In macrocytic anemia MCH may be as high as 39 pg but MCHC stays within normal."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "7", "q": "What is MCHC and how is it calculated?", "a": ["Mean corpuscular hemoglobin concentration: the average amount of Hb in 100 ml RBCs. It shows the actual Hb content in red cells only (not the whole blood).", "MCHC = (Hb / H.V) x 100 = 34 gm/dl (normal 30-36). Another way: MCHC = MCH / MCV.", "Normal range: normochromic. Below normal: hypochromic. It cannot be hyperchromic because the maximum Hb capacity of RBCs is 36%."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "6", "q": "Blood indices objectives and relevance.", "a": ["Objectives: 1. Explain the clinical significance of calculating the blood indices. 2. Describe normal corpuscular values and how to obtain them. 3. Describe classification of anemia based on these standards.", "Relevance: they are important in determining the type and cause of anemia.", "Apparatus: measuring the Hb level (discussed), measuring the hematocrit (HV), and RBC counting by hemocytometer."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "7", "q": "Classification of anemia by the blood indices: what does the file say?", "a": ["MCHC: if within the normal range (30-36 gm%), normochromic; if below normal, hypochromic. It cannot be hyperchromic, because the maximum capacity for Hb is 36%, the upper limit of the normal range.", "MCV normal is 90 cubic micrometers (74-95); MCH normal is 30 picograms (27-32).", "In macrocytic anemia the MCH may be as high as 39 pg, but the MCHC stays within normal.", "The file does not give a full table classifying anemias by MCV and MCH."], "src": "f", "lo": 0}, {"s": "Blood indices", "p": "7", "q": "What is the upper limit of Hb concentration inside the RBCs?", "a": ["The upper limit for the Hb concentrating capacity inside the RBCs is 36% only, i.e. a maximum of 36% of the RBC capacity can be occupied by Hb. MCHC represents the actual Hb content in red cells only (not the whole blood), and the relationship between the red cell volume and the degree of saturation with Hb."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "8", "q": "Explain the ABO system (agglutinogens and agglutinins).", "a": ["People are divided into 4 groups by the presence or absence of 2 agglutinogens (A and B) on the red cells. Plasma has specific agglutinins (Anti-A and Anti-B).", "Group A has Anti-B in plasma. Group B has Anti-A. Group AB has no antibodies. Group O has both Anti-A and Anti-B.", "Rule 1: if an agglutinogen is present on the red cells, the matching agglutinin must be absent from the plasma. Rule 2: if an agglutinogen is absent, the matching agglutinin must be present."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "9", "q": "How do you determine the ABO and Rh groups?", "a": ["ABO: mark one end of the slide A and the other B; sterilize the finger, lance it, put one drop of blood on each end; add anti-A serum to side A and anti-B serum to side B; mix by rocking the slide 1-2 minutes; look for agglutination (looks like red pepper grains).", "Rh: mix 2 drops of blood with one drop of anti-D serum on a dry clean slide; rock gently 2-3 minutes; check under the microscope if in doubt. The Rh reaction is weaker and less easy to detect than A and B."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "9", "q": "What is the Rh system?", "a": ["The Rh antigen is present only on the surface of RBCs. Rh positive means the D antigen is present (85% of the population). Rh negative means the D antigen is absent (15%). It is detected by strong anti-D serum."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "8, 10", "q": "Importance of the ABO system (the lines are blank on p.10; this is what the file says about it).", "a": ["The file says ABO and Rh are the blood group systems of clinical importance (p.8).", "Clinical significance (p.8 objectives): it is essential to match donor and recipient blood groups before a transfusion, because mismatched transfusion has harmful effects. It also gives the basis of the terms universal donor and universal recipient (Landsteiner's law).", "Basis (p.8): group A has anti-B, group B has anti-A, group AB has no antibodies, group O has both anti-A and anti-B. If an agglutinogen is present in the red cells, the matching agglutinin is absent from the plasma; if it is absent, the agglutinin is present."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "10", "q": "Importance and dangers of the Rh antigens (p.10). What does the file say about Rh antibodies?", "a": ["Significance (p.10): Rh incompatibility results in a hemolytic transfusion reaction and hemolytic disease of the newborn.", "Unlike the ABO system, there are no naturally occurring antibodies against Rh antigens in Rh negative people.", "Immune antibodies develop against Rh antigen after exposure following transfusion or pregnancy, and can be detected by the Coombs test (antiglobulin test)."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "8", "q": "Blood groups objectives: what should you be able to do?", "a": ["1. Describe the physiological basis of blood grouping and its clinical significance.", "2. Describe Landsteiner's law and explain the basis of the terms universal donor and universal recipient.", "3. Describe the Rh factor, how it was discovered and its clinical significance.", "4. Determine blood groups by using commercially available antisera, and precautions to be taken.", "5. Explain how blood is stored in blood banks, and the changes that occur in blood during storage.", "6. List the indications of blood transfusion and the dangers associated with it.", "7. Explain why it is essential to match donor and recipient blood groups before giving a transfusion.", "8. Describe the effects of mismatched blood transfusion."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "8", "q": "How many blood group systems are there, and which are clinically important?", "a": ["There are more than 300 blood group systems. ABO and Rh (Rhesus) are the ones of clinical importance.", "In the ABO system humans are divided into 4 main groups according to the presence or absence of 2 different agglutinogens (A and B) on the surface of their red blood cells. The plasma contains the specific agglutinins (antibodies) anti-A and anti-B."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "8-9", "q": "Blood storage, indications and dangers of transfusion, universal donor and recipient: what does the file say?", "a": ["The file lists these only as objectives (2, 5, 6, 7 and 8). It gives no text for how blood is stored, the changes during storage, the indications of transfusion, the dangers, or the explanation of universal donor and recipient.", "What it does give is the ABO rules: an agglutinogen present in the red cells means the matching agglutinin is absent from the plasma; absent means present. And the Rh significance: Rh incompatibility results in a hemolytic transfusion reaction and hemolytic disease of the newborn."], "src": "f", "lo": 0}, {"s": "Blood groups", "p": "9", "q": "What materials and steps are used for blood grouping, and what are the precautions?", "a": ["Materials: sterile lancet, alcohol swab, anti-A, anti-B and anti-D sera, glass marking pencil and microscope.", "ABO: mark one end of the slide A and the other B; sterilize the finger with alcohol and let it dry; lance the finger and place one drop of blood on each end; add one drop of anti-A to side A and anti-B to side B; mix by rocking the slide gently to and fro for 1-2 minutes; look for agglutination, which looks like red pepper grains.", "Rh: mix 2 drops of blood with one drop of anti-D serum on a dry clean slide, rock gently for 2-3 minutes, and check under the microscope if in doubt. The Rh factor is usually weaker than the A and B agglutinogens, so the agglutination is not as strong or as easy to detect."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11", "q": "Define hemostasis and thrombosis.", "a": ["Hemostasis (Greek: haema = blood, stasis = halt): the process of stoppage of bleeding after blood vessels are damaged.", "Thrombosis: clotting of blood within an unbroken blood vessel, usually by a roughened endothelium due to atherosclerosis, infection or injury."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11", "q": "List the tests for hemostasis.", "a": ["Bleeding time, clot lysis time, coagulation time, capillary fragility test (Hess test), platelet count, Ivy bleeding time, PT and PTT, clot retraction time.", "Bleeding time and coagulation time are simple tests used as a routine before every minor and major surgery (e.g. tooth extraction, biopsy) and before and during anticoagulant therapy."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11-12", "q": "What is bleeding time and how is it measured (Duke method)?", "a": ["Bleeding time: the time from the skin injury to the stoppage of bleeding. It depends on local vasoconstriction and platelet plug formation (a test of platelet function).", "Duke method: sterilize the earlobe; scrub with alcohol to increase blood flow; small injury (3-4 mm deep) with a sterile pin; remove blood with filter paper at intervals without squeezing or pressing; record the time from injury to stoppage.", "Fingertip is not preferred (thick in some people). If bleeding goes on more than 10-12 minutes, stop, press with sterile gauze and inform the teacher."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "12", "q": "What is the normal bleeding time and what does it depend on?", "a": ["Normal bleeding time = 1-5 minutes.", "It depends on: depth of the wound, rate of blood flow to the skin, the platelet count, and the condition of the blood vessel wall."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "12", "q": "What are the causes of prolonged bleeding time?", "a": ["I. Platelet disorders: a) thrombocytopenia (number below 50,000/cmm, quantitative): primary (unknown cause) or secondary (aplasia of bone marrow due to X ray, radioactive substances, neoplastic deposits, drug sensitivity). b) thrombasthenia (defect in function, qualitative): primary, or secondary (severe uremia, von Willebrand disease, drugs such as aspirin).", "II. Vascular disorders: vitamin C deficiency."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "12-13", "q": "What is coagulation time and what are its methods and normal values?", "a": ["Coagulation time: the time from start of bleeding to formation of fibrin threads. It depends on blood coagulation factors.", "A. Capillary blood: 1) Wright capillary glass tube method (more accurate): normal 3-6 min. 2) Drop method (pin drawn through a drop every 30 seconds): normal 2-4 min.", "B. Venous blood (Lee and White tube method, tube in water bath at 37 C tilted every 30 seconds): normal 5-10 min."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "13", "q": "What are the causes of prolonged coagulation time?", "a": ["1) Hemophilia (A = factor VIII, B = IX, C = XI). 2) Vitamin K deficiency. 3) Liver disease (factors II, VII, IX and X) and obstructive jaundice. 4) Use of anticoagulants."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "14-15", "q": "What is a thrombus and what are emboli? What are the causes and complications?", "a": ["Thrombus: an abnormal clot that develops in a blood vessel. Emboli: freely flowing clots.", "Causes of thromboembolic conditions: 1) a roughened endothelial surface (arteriosclerosis, infection or trauma); 2) blood often clots when it flows very slowly.", "Complications: obstruction of arterial supply gives ischemia and necrosis of the organ; obstruction of venous drainage gives edema. Emboli from large arteries or the left heart plug arteries or arterioles in brain, kidneys or elsewhere. Emboli from the venous system or the right heart cause pulmonary arterial embolism."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "15", "q": "What is the prophylaxis and treatment of thromboembolism?", "a": ["Prophylaxis: avoid prolonged recumbence; use anticoagulants in susceptible patients.", "Treatment: TPA to dissolve the clot."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "15", "q": "Compare heparin and dicumarol.", "a": ["Heparin (injected): origin mast cells and basophils; facilitates antithrombin III (against IXa, Xa, XIa, XIIa); acts in vivo and in vitro; rapid onset; short duration; by injection; antidote protamine sulfate 1%.", "Dicumarol (oral): plant origin; inhibits activation of vitamin K so inhibits formation of prothrombin and factors VII, IX, X; acts only in vivo; delayed onset; long duration; given orally; antidote vitamin K.", "Blood transfusion is the antidote for both."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "10-11", "q": "Hemostasis objectives: what should you be able to do?", "a": ["1. Indicate the clinical importance of doing bleeding time and coagulation time.", "2. Define hemostasis and describe how bleeding stops from a finger prick.", "3. Determine bleeding time and coagulation time by the routine laboratory methods and give their normal values.", "4. Name the conditions in which bleeding time and coagulation time are increased.", "5. Describe the physiological basis of bleeding disorders.", "6. Explain the relevance of doing platelet count and indicate their role in hemostasis and thrombosis.", "7. List the clotting factors and describe the steps in the intrinsic and extrinsic pathways of coagulation.", "8. Describe how clotting occurs in vivo and in vitro.", "9. Define the terms thrombosis and embolism.", "10. Indicate how clotting can be prevented in vivo and in vitro."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11", "q": "What is the relevance of the hemostasis tests, and when are bleeding and coagulation time used?", "a": ["Relevance: a disease is suspected when there is frequent and prolonged bleeding with minor injuries, or sometimes spontaneous bleeding.", "Bleeding time and coagulation time are two simple tests that can be used as a routine before every minor and major surgery, e.g. tooth extraction, biopsy procedure, and before and during anticoagulant therapy."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11", "q": "What materials are needed for the bleeding time test?", "a": ["1. Equipment for a sterilized finger prick.", "2. Clean filter paper.", "3. Clean capillary tubes.", "4. Stopwatch."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11", "q": "What does bleeding time depend on, and what kind of test is it?", "a": ["Definition: the time passed from the skin injury to the stoppage of bleeding.", "It depends on local vasoconstriction and platelet plug formation, i.e. it is an in vitro test of platelet function (as written in the file)."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "12-13", "q": "What are the precautions of the Duke method for bleeding time?", "a": ["Scrub the chosen skin site with alcohol to increase blood flow; small injury 3-4 mm deep to the earlobe with a sterilized pin; remove the blood with filter paper at intervals to prevent clot formation; do not squeeze or press the filter paper on the puncture site.", "The fingertip is not preferred because it is quite thick in some persons.", "If bleeding continues for more than 10-12 minutes, stop the test, press with sterilized gauze on the wound and inform your teacher."], "src": "f", "lo": 0}, {"s": "Hemostasis", "p": "11-15", "q": "Clotting factors, intrinsic and extrinsic pathways, clotting in vivo and in vitro, and prevention: what does the file say?", "a": ["The file lists these as objectives (7, 8 and 10) but does not give text on the clotting factors or the steps of the two pathways.", "Anticoagulants (p.15): heparin is injected, comes from mast cells and basophils, acts by facilitating antithrombin III, works in vivo and in vitro, with rapid onset and short duration, antidote protamine sulfate 1%. Dicumarol is oral, of plant origin, inhibits activation of vitamin K, works only in vivo, with delayed onset and long duration, antidote vitamin K. Blood transfusion is the antidote for both.", "Prophylaxis of thromboembolism: avoid prolonged recumbence and use anticoagulants in susceptible patients. Treatment: TPA to dissolve the clot."], "src": "f", "lo": 0}];
